<?php
declare(strict_types=1);
require_once __DIR__ . '/../repositories/PollRepository.php';
final class PCPollService {
 public static function create(int $uid,int $cid,array $d):array { if($cid<1||!PCPollRepository::member(pc_db(),$cid,$uid))return ['status'=>404,'body'=>['ok'=>false,'error'=>'conversation_not_found']];$q=is_string($d['question']??null)?trim($d['question']):'';$opts=$d['options']??null;if($q===''||pc_len($q)>300)return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_question']];if(!is_array($opts)||count($opts)<2||count($opts)>10)return ['status'=>422,'body'=>['ok'=>false,'error'=>'poll_requires_2_to_10_options']];$clean=[];foreach($opts as $o){if(!is_string($o))return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_option']];$o=trim($o);if($o===''||pc_len($o)>120)return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_option']];$clean[]=$o;}if(count(array_unique(array_map(static fn(string $v):string=>function_exists('mb_strtolower')?mb_strtolower($v,'UTF-8'):strtolower($v),$clean)))!==count($clean))return ['status'=>422,'body'=>['ok'=>false,'error'=>'duplicate_poll_options']];$multiple=$d['allow_multiple']??false;$anonymous=$d['anonymous']??true;if(!is_bool($multiple)||!is_bool($anonymous))return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_settings']];$close=null;if(isset($d['closes_at'])&&$d['closes_at']!==''){if(!is_string($d['closes_at'])||strtotime($d['closes_at'])===false||strtotime($d['closes_at'])<=time())return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_close_time']];$close=gmdate('Y-m-d H:i:s',strtotime($d['closes_at']));}$id=PCPollRepository::create(pc_db(),$cid,$uid,['question'=>$q,'options'=>$clean,'allow_multiple'=>$multiple,'anonymous'=>$anonymous,'closes_at'=>$close]);return ['status'=>201,'body'=>['ok'=>true,'poll'=>PCPollRepository::get(pc_db(),$id,$uid)]]; }
 public static function get(int $uid,int $id):array { if($id<1)return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_id']];$p=PCPollRepository::get(pc_db(),$id,$uid);return $p?['status'=>200,'body'=>['ok'=>true,'poll'=>$p]]:['status'=>404,'body'=>['ok'=>false,'error'=>'poll_not_found']]; }
 public static function vote(int $uid,int $id,mixed $raw):array { if($id<1||!is_array($raw)||count($raw)<1||count($raw)>10)return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_votes']];$ids=[];foreach($raw as $v){$n=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$n)return ['status'=>422,'body'=>['ok'=>false,'error'=>'invalid_poll_option_id']];$ids[]=(int)$n;}$ids=array_values(array_unique($ids));return PCPollRepository::vote(pc_db(),$id,$uid,$ids); }
}
